import{_ as a,c as r,o as d,a0 as c}from"./chunks/framework.DE5X-pmd.js";const g=JSON.parse('{"title":"Scratch 编辑器","description":"","frontmatter":{},"headers":[],"relativePath":"guide/scratch.md","filePath":"guide/scratch.md"}'),e={name:"guide/scratch.md"};function o(s,t,h,n,i,l){return d(),r("div",null,[...t[0]||(t[0]=[c('<h1 id="scratch-编辑器" tabindex="-1">Scratch 编辑器 <a class="header-anchor" href="#scratch-编辑器" aria-label="Permalink to &quot;Scratch 编辑器&quot;">​</a></h1><p><code>CodeNova</code> 平台集成了<strong>Scratch 编辑器</strong>（Scratch-gui.4.0.43），并对其进行了二次开发（下文语境无特殊说明，Scratch 编辑器指二次开发后的编辑器），增加一些教学工具。学生使用的工具放置在顶端的菜单栏中，而教师工具统一收纳到右侧cat 下拉菜单中。</p><p>教师可以在这里编辑程序，并把包含完整程序的Scratch项目保存到课程中。此时编辑器将额外生成一个过滤积木块，只有素材的项目供学生使用，所以学生打开课程即可获取素材，无需依赖U盘逐台设备拷贝，Scratch 编辑器的其它功能如下：</p><table tabindex="0"><thead><tr><th>功能</th><th>说明</th><th>使用者</th><th>位置</th></tr></thead><tbody><tr><td>显示行号</td><td>积木区显示行号，方便定位积木</td><td>教师/学生</td><td>cat 菜单</td></tr><tr><td>画板</td><td>浮动的便签，可输入文本</td><td>教师</td><td>cat 菜单</td></tr><tr><td>积木白名单</td><td>勾选积木，学生版只保留这些</td><td>教师</td><td>cat 菜单</td></tr><tr><td>保存到课程</td><td>一键保存 main.sb3（完整版）+ student.sb3（学生版）</td><td>教师</td><td>cat 菜单</td></tr><tr><td>缩放</td><td>开启或关闭全屏Scratch编辑器（全屏可获取更佳视觉体验）</td><td>学生/教师</td><td>顶端栏</td></tr><tr><td>示例</td><td>点「示例」浮动预览完整项目效果，可供学生参考</td><td>学生/教师</td><td>顶端栏</td></tr></tbody></table><h2 id="详细说明" tabindex="-1">详细说明 <a class="header-anchor" href="#详细说明" aria-label="Permalink to &quot;详细说明&quot;">​</a></h2><h3 id="_1-cat-菜单-scratch-cat" tabindex="-1">1. cat 菜单（scratch-cat） <a class="header-anchor" href="#_1-cat-菜单-scratch-cat" aria-label="Permalink to &quot;1. cat 菜单（scratch-cat）&quot;">​</a></h3><p>编辑器的教师/学生工具都收纳在 <strong>scratch-cat（cat）菜单</strong>里，包含：</p><p><strong>显示行号</strong> — 打开后积木区显示行号，方便教学时定位积木块</p><p><strong>画板</strong> — 编辑器内浮动的<strong>文字便签</strong>，可以随手记录要点。支持3种颜色（黑色/重点/辅助）、字号、加粗，可拖动、可调整大小。内容自动保存在本机浏览器，教学板书或作品记要。</p><p><strong>积木白名单</strong> — Scratch 编辑器默认会过滤所有程序，不过学生可以获取白名单勾选的积木。</p><ol><li>在 cat 菜单中开启「积木白名单」</li><li>勾选本次需要保留给学生的积木</li><li>后续保存到学生课件时，学生版程序将按白名单过滤</li></ol><p><strong>保存到课程</strong>（教师/管理员专属） — 把课件一键保存到指定课程，通过弹窗进行选择课程。（需在教师后台提前新建课程）</p><h3 id="_2-顶端栏功能" tabindex="-1">2. 顶端栏功能 <a class="header-anchor" href="#_2-顶端栏功能" aria-label="Permalink to &quot;2. 顶端栏功能&quot;">​</a></h3><p><strong>缩放</strong> — 编辑区提供缩放控制，可开启或取消全屏显示，类似按 F11。</p><p><strong>示例</strong> — 打开课件后，菜单栏全屏按钮旁有「示例」按钮。点击会弹出浮动预览面板，预览完整项目的运行效果。</p><h2 id="三、常见问题" tabindex="-1">三、常见问题 <a class="header-anchor" href="#三、常见问题" aria-label="Permalink to &quot;三、常见问题&quot;">​</a></h2><p><strong>Q：为什么学生打开课件和我做的不一样？</strong> A：学生加载的是学生版（student.sb3），它按白名单过滤过。如果教师登录了账号，加载的是完整版。</p><p><strong>Q：保存到课程和保存到电脑有什么区别？</strong> A：保存到电脑会使用了浏览器下载到本地；保存到课程会传到平台的课件目录，学生可在线打开。</p>',18)])])}const _=a(e,[["render",o]]);export{g as __pageData,_ as default};
